import type {ScopeType} from '../models/enums'

const getScopeLabel = (scope: ScopeType): string => {
  switch (scope) {
    case 'SCOPE_TYPE_REPO':
      return 'repository'
    case 'SCOPE_TYPE_ENTERPRISE':
      return 'enterprise'
    case 'SCOPE_TYPE_ORG':
    default:
      return 'organization'
  }
}

